"""Build a browsable, static channel catalog with progressive search/filtering."""
import json
from html import escape as e
from pathlib import Path
from urllib.parse import quote
ROOT=Path(__file__).resolve().parent.parent
LABELS={'fieldwork':'Field visits','conversation':'Conversations','museum':'Museum collections','short':'Shorts'}
def main():
    data=json.loads((ROOT/'data/ancientatlas-channel.json').read_text())
    cards=[]
    for x in data['items']:
        ident=x['id'];kind=x['kind'];duration=x.get('duration');dur=f'{int(duration)//60}:{int(duration)%60:02d}' if duration else ''
        watch=x['url']+(('&' if '?' in x['url'] else '?')+f't={x["start"]}s' if x.get('start') else '')
        sites=''.join(f'<a class="place" href="/?site={quote(s,safe="")}">Explore {e(s)} on the map →</a>' for s in x.get('sites',[]))
        if not sites and x.get('related_sites'):
            sites=''.join(f'<a class="place" href="/?site={quote(s,safe="")}">Explore {e(s)} (discussed) →</a>' for s in x['related_sites'])
        credit=x.get('credit','Ancient Atlas')
        cards.append(f'''<article class="film" data-kind="{kind}" data-search="{e((x['title']+' '+credit+' '+' '.join(x.get('sites',[]))).lower(),quote=True)}"><a class="thumb" href="{e(watch,quote=True)}" aria-label="Watch {e(x['title'],quote=True)} on YouTube"><img src="https://i.ytimg.com/vi/{ident}/hqdefault.jpg" alt="" width="480" height="360" loading="lazy" decoding="async">{f'<span class="duration">{dur}</span>' if dur else ''}</a><div class="film-copy"><p class="eyebrow">{LABELS[kind]}</p><h2><a href="{e(watch,quote=True)}">{e(x['title'])}</a></h2><p class="credit">{e(credit)}</p><a class="watch" href="{e(watch,quote=True)}">Watch on YouTube ↗</a>{sites}</div></article>''')
    counts={k:sum(x['kind']==k for x in data['items']) for k in LABELS}
    buttons='<button type="button" data-filter="all" aria-pressed="true">All '+str(len(cards))+'</button>'+''.join(f'<button type="button" data-filter="{k}" aria-pressed="false">{v} {counts[k]}</button>' for k,v in LABELS.items())
    page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ancient Atlas films and Shorts | The Ancient Atlas</title><meta name="description" content="Field visits, conversations and museum films from Ancient Atlas. Find a film, explore its place, and discover the creators who walk the ground."><link rel="canonical" href="https://theancientatlas.com/creators/ancient-atlas"><meta property="og:image" content="https://theancientatlas.com/og-image.png"><meta property="og:title" content="Ancient Atlas on film"><link rel="icon" href="/favicon.ico"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Fraunces:opsz,wght@9..144,500;9..144,600&display=swap" rel="stylesheet"><style>
:root{color-scheme:dark;--bg:#0D0D12;--panel:#17171F;--ink:#F0EEE9;--muted:#C5C5D0;--gold:#C9A84C}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 Inter,system-ui,sans-serif}a{color:inherit;text-underline-offset:4px}a:hover{color:var(--gold)}.wrap{max-width:1200px;margin:auto;padding:0 clamp(20px,4vw,48px)}nav{display:flex;flex-wrap:wrap;align-items:center;gap:12px 25px;padding:20px 0;border-bottom:1px solid #34313b;font-size:14px}nav a{padding:7px 0}.brand{margin-right:auto;color:var(--gold);text-decoration:none}header{padding:32px 0 24px;max-width:780px}h1{font:500 clamp(38px,5vw,60px)/1.08 Fraunces,Georgia,serif;margin:16px 0 24px}.eyebrow{color:var(--gold);font-size:12px;letter-spacing:.12em;text-transform:uppercase;margin:0 0 10px}.deck{font-size:19px;color:var(--muted)}.channel{display:inline-block;border:1px solid var(--gold);padding:12px 18px;text-decoration:none;border-radius:4px;margin:10px 0}.others{padding:22px 26px;background:var(--panel);border-left:3px solid var(--gold);margin:0 0 32px}.others p{margin:0 0 8px}.others a{display:inline-block;margin:5px 20px 5px 0;color:var(--gold)}.controls{padding:12px 0 25px}.filters{display:flex;gap:9px;flex-wrap:wrap;margin-top:16px}button,input{font:inherit}button{min-height:44px;padding:9px 14px;background:var(--panel);color:var(--ink);border:1px solid #55515d;border-radius:4px;cursor:pointer}button[aria-pressed=true]{background:var(--gold);color:var(--bg);border-color:var(--gold)}label{display:block;margin-bottom:7px}input{width:100%;max-width:480px;background:var(--panel);border:1px solid #77717f;border-radius:4px;color:var(--ink);padding:12px}.count{color:var(--muted);margin:18px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:30px 24px}.film{min-width:0;background:var(--panel);border:1px solid #302d38;border-radius:5px;overflow:hidden}.thumb{position:relative;display:block;aspect-ratio:16/9;overflow:hidden}.thumb img{width:100%;height:100%;object-fit:cover}.duration{position:absolute;right:10px;bottom:9px;background:#0d0d12e8;padding:2px 7px;font-size:13px}.film-copy{padding:20px}h2{font:500 22px/1.3 Fraunces,Georgia,serif;margin:0 0 12px}h2 a{text-decoration:none}.credit{font-size:13px;color:var(--muted)}.watch,.place{display:block;font-size:14px;margin-top:14px;color:var(--gold)}footer{padding:40px 0;color:var(--muted);font-size:13px}[hidden]{display:none!important}:focus-visible{outline:3px solid var(--ink);outline-offset:4px}.skip{position:absolute;left:20px;top:-80px;background:var(--bg);padding:12px;z-index:5}.skip:focus{top:10px}@media(max-width:950px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.grid{grid-template-columns:1fr}header{padding-top:36px}.brand{flex-basis:100%}.others{padding:20px}.film-copy{padding:18px}}
</style><script defer src="/assets/js/analytics.js"></script><script data-goatcounter="https://ancientatlas.goatcounter.com/count" async src="//gc.zgo.at/count.js"></script></head><body><a class="skip" href="#main">Skip to films</a><div class="wrap"><nav aria-label="Main"><a class="brand" href="/">THE ANCIENT ATLAS</a><a href="/">Map</a><a href="/sites/">Sites</a><a href="/creators/">All creators</a><a href="/library/">Library</a><a href="/patterns/">Patterns</a></nav><main id="main"><header><p class="eyebrow">From the people behind the map</p><h1>Ancient Atlas on film</h1><p class="deck">Walk the ground with us. Listen to the people who study it. Find your next place to look closer.</p><a class="channel" href="https://www.youtube.com/@AncientAtlasMap">Follow @AncientAtlasMap on YouTube ↗</a></header><aside class="others" aria-label="Discover other creators"><p><strong>One place. More than one perspective.</strong></p><p>The Atlas grows through the people who carry a camera into the field. Keep exploring their work.</p><a href="/creators/">Explore all creators →</a><a href="https://www.youtube.com/@StoneRiddles">Stone Riddles ↗</a><a href="https://www.youtube.com/@MegalithomaniaUK">Megalithomania ↗</a><a href="https://www.youtube.com/@solsticehunter">Solstice Hunter ↗</a></aside><div class="controls" id="controls" hidden><label for="search">Find a film or place</label><input id="search" type="search" placeholder="Try Peru, UnchartedX, or Moray"><div class="filters" role="group" aria-label="Film type">'''+buttons+'''</div><p class="count" id="count" role="status" aria-live="polite"></p></div><p id="empty" hidden>No films match. Try another word or choose All.</p><div class="grid">'''+''.join(cards)+'''</div></main><footer>Catalog checked '''+e(data['checked'])+'''. Films open on YouTube. Map links return you to the place and its other creators.<br><a href="/creators/">Discover more creators</a> · <a href="/contact">Suggest a film or correction</a></footer></div><script>
(()=>{const cards=[...document.querySelectorAll('.film')],buttons=[...document.querySelectorAll('[data-filter]')],search=document.getElementById('search');let kind='all';function update(){const q=search.value.trim().toLocaleLowerCase();let n=0;for(const card of cards){const show=(kind==='all'||card.dataset.kind===kind)&&card.dataset.search.includes(q);card.hidden=!show;if(show)n++}document.getElementById('count').textContent=`${n} of ${cards.length} films and Shorts`;document.getElementById('empty').hidden=n>0}for(const b of buttons)b.addEventListener('click',()=>{kind=b.dataset.filter;for(const other of buttons)other.setAttribute('aria-pressed',String(other===b));update()});search.addEventListener('input',update);document.getElementById('controls').hidden=false;update()})();
</script></body></html>'''
    (ROOT/'public/creators/ancient-atlas.html').write_text(page)
if __name__=='__main__':main()
